			/**
			 * 문제상태및원인분류코드 상위분류 선택시 하위 분류가 없는경우 비활성화 처리 
			 * @param {Number} vsNewVal 선택한 분류콤보박스 value
			 * @param {String} codeId 선택한 분류 공통코드 아이디
			    PROBM_STTS_LCLAS_SE_CD 문제상태대분류
			    PROBM_STTS_MLSFC_SE_CD 문제상태중분류
			    PROBM_STTS_SCLAS_SE_CD 문제상태소분류
			    PROBM_CAS_LCLAS_SE_CD  문제원인대분류
			    PROBM_CAS_SCLAS_SE_CD  문제원인소분류
			 */
			function selectProbmSection(vsNewVal, CodeId, psState) {
			    
			    // param Null 일경우 return false
			    //    if (ValueUtil.isNull(vsNewVal)) return false;
			    if (ValueUtil.isNull(CodeId)) return false;
			    
			    // 상위코드 선택여부 체크
			    //comboSelectUpCmmnsCheck(CodeId);
			    
			    // 문제상태대분류, 문제원인대/소분류 기타(입력 선택시)
			    //    comboEtcValueCheck(CodeId);
			    
			    // 문제상태및원인 분류 콤보박스
			    var vcCmbProbmLv2 = app.lookup("cmb14");
			    var vcCmbProbmLv3 = app.lookup("cmb15");
			    var vcCmbProbmLv4 = app.lookup("cmb16");
			    var vcCmbProbmLv5 = app.lookup("cmb17");
			    
			    // 문제상태대분류
			    if (CodeId == "PROBM_STTS_LCLAS_SE_CD") {
			        // 대분류 선택에 따른 하위 콤보 값 필터링
			        vcCmbProbmLv2.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        vcCmbProbmLv3.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        vcCmbProbmLv4.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        vcCmbProbmLv5.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        // 대분류 변경시 하위 콤보 초기화
			        if (psState != "UPDATE") {
			            vcCmbProbmLv2.putValue("");
			            vcCmbProbmLv3.putValue("");
			            vcCmbProbmLv4.putValue("");
			            vcCmbProbmLv5.putValue("");
			        }
			        
			        // 문제상태중분류
			    } else if (CodeId == "PROBM_STTS_MLSFC_SE_CD") {
			        // 중분류 선택에 따른 하위 콤보 값 필터링
			        vcCmbProbmLv3.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			//        vcCmbProbmLv4.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			//        vcCmbProbmLv5.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        // 중분류 변경시 하위 콤보 초기화
			        if (psState != "UPDATE") {
			            vcCmbProbmLv3.putValue("");
			            vcCmbProbmLv4.putValue("");
			            vcCmbProbmLv5.putValue("");
			        }
			        
			        // 문제상태소분류
			    } else if (CodeId == "PROBM_STTS_SCLAS_SE_CD") {
			        // 소분류 선택에 따른 하위 콤보 값 필터링
			//        vcCmbProbmLv4.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			//        vcCmbProbmLv5.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        // 소분류 변경시 하위 콤보 초기화
			        if (psState != "UPDATE") {
			            vcCmbProbmLv4.putValue("");
			            vcCmbProbmLv5.putValue("");
			        }
			        
			        // 문제원인대분류
			    } else if (CodeId == "PROBM_CAS_LCLAS_SE_CD") {
			        // 대분류 선택에 따른 하위 콤보 값 필터링
			        vcCmbProbmLv5.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        // 대분류 변경시 하위 콤보 초기화
			        if (psState != "UPDATE") {
			            vcCmbProbmLv5.putValue("");
			        }
			    }
			    
			    // 하위분류 콤보박스 rowCount 개수 확인
			    var rowCnt = [vcCmbProbmLv2.getItemCount(), vcCmbProbmLv3.getItemCount(), vcCmbProbmLv4.getItemCount(), vcCmbProbmLv5.getItemCount()];
			    rowCnt.forEach(function(rowCnt, idx) {
			        //console.log("rowCnt=[" + idx + "] = " + rowCnt + "");
			        
			        // 하위분류가 유무 여부 체크
			        if (rowCnt == 1) {
			            /* 하위분류 없음 */
			            switch (idx) {
			                case 0:
			                    util.Control.setEnable(app, false, "cmb14");
			                    break;
			                case 1:
			                    util.Control.setEnable(app, false, "cmb15");
			                    break;
			                case 2:
			                    util.Control.setEnable(app, false, "cmb16");
			                    
			                    break;
			                case 3:
			                    util.Control.setEnable(app, false, "cmb17");
			                    break;
			            }
			        } else {
			            switch (idx) {
			                case 0:
			                    util.Control.setEnable(app, true, "cmb14");
			                    break;
			                case 1:
			                    util.Control.setEnable(app, true, "cmb15");
			                    break;
			                case 2:
			                    util.Control.setEnable(app, true, "cmb16");
			                    break;
			                case 3:
			                    util.Control.setEnable(app, true, "cmb17");
			                    break;
			            }
			        }
			    });
			}

			/*
			 * 사용하지 않는 함수 - 2023.04.18
			 */
